mapper.select:
SELECT BOARD_ID, TITLE, CONTENT, WRITER, REG_DT
  FROM BOARD
 WHERE BOARD_ID = #{boardId}

mapper.update:
UPDATE BOARD
   SET TITLE = #{title},
       CONTENT = #{content},
       WRITER = #{writer}
 WHERE BOARD_ID = #{boardId}

mapper.select:
SELECT FILE_ID, BOARD_ID, ORIGINAL_NAME, STORED_NAME, FILE_SIZE, CONTENT_TYPE, REG_DT
  FROM BOARD_FILE
 WHERE FILE_ID = #{fileId}
